import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import crypto from 'node:crypto';
import { spawn, execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { fileURLToPath } from 'node:url';

const execFileAsync = promisify(execFile);
const root = 'D:/ClaudeProjects/ai_acknowladge';
const sourcePath = fileURLToPath(import.meta.url);
const pythonPath = sourcePath.replace(/\.mjs$/, '.py');
const source = fs.readFileSync(sourcePath, 'utf8');
const pythonSource = fs.readFileSync(pythonPath, 'utf8');
const sha = (value) => crypto.createHash('sha256').update(value).digest('hex');
const runId = crypto.randomBytes(6).toString('hex');
const group = 'zhiliao_a2_tick_' + runId;
const priorPath = path.join(root, 'docs/验收证据/story-2-2-tick-maintenance-2026-09-12T05-48-48-326Z.json');
const prior = JSON.parse(fs.readFileSync(priorPath, 'utf8'));
const files = [...new Set([...prior.preservation.files.map((entry) => entry.path),
  ...fs.readdirSync(path.join(root, 'docs/验收证据')).filter((file) => /^story-2-2.*\.json$/.test(file)).map((file) => 'docs/验收证据/' + file)])];
const report = {
  story: '2.2', recorded_at: new Date().toISOString(), status: 'failed',
  run_id: runId, group, baseline_commit: prior.baseline_commit,
  authorization: '用户在最长 30 秒内核跟踪方案后回复“继续确认”；仅本次跟踪配置与清理，不写时钟参数、不启停服务或重启',
  scope: '使用私有 tracefs 实例记录 do_adjtimex 入口与返回，核对 ADJ_TICK 请求，单次有界采集',
  host: { platform: process.platform, release: os.release(), node: process.version },
  source_file: path.basename(sourcePath), source_sha256: sha(source), maintenance_source: source,
  python_source_file: path.basename(pythonPath), python_source_sha256: sha(pythonSource), python_source: pythonSource,
  prior_maintenance_sha256: sha(fs.readFileSync(priorPath)),
  preparation_fix: '首次准备阶段修正 open(a) 的 EINVAL；第二次按进程名匹配只读对照未成功，2.1 秒内停止并清理。本次按同源 mono_raw 调用时间窗唯一匹配只读对照，时长缩为 25 秒，两段实际采集合计保持在 30 秒以内',
  prior_trace_attempt_sha256: sha(fs.readFileSync(path.join(root, 'docs/验收证据/story-2-2-tick-trace-2026-09-12T06-33-12-041Z.json'))),
  prior_incomplete_trace_sha256: sha(fs.readFileSync(path.join(root, 'docs/验收证据/story-2-2-tick-trace-2026-09-12T06-45-28-312Z.json'))),
  capture_budget_ms: 30000, planned_guest_capture_ms: 25000, previous_capture_host_upper_ms: 2096.9204,
  proxy: { status: 'not_run', reason: '本轮仅跟踪，尚未修复计时偏差' },
  limitations: ['本次跟踪不证明时钟已修复或 A2 代理时限通过。', 'trace_pid 为内核任务标识，跨 PID 命名空间的数字匹配或截断名称不能单独证明进程身份。']
};
const evidencePath = path.join(root, 'docs/验收证据/story-2-2-tick-trace-' + report.recorded_at.replaceAll(':', '-').replace('.', '-') + '.json');
const format = '{"id":{{json .Id}},"name":{{json .Name}},"image":{{json .Image}},"status":{{json .State.Status}},"exit_code":{{json .State.ExitCode}},"started_at":{{json .State.StartedAt}},"finished_at":{{json .State.FinishedAt}},"project":{{json (index .Config.Labels "com.docker.compose.project")}},"mounts":{{json .Mounts}},"networks":{{json .NetworkSettings.Networks}}}';
async function invoke(file, args) {
  const result = await execFileAsync(file, args, { cwd: root, windowsHide: true, encoding: 'utf8', timeout: 10000, maxBuffer: 1024 * 1024 });
  return result.stdout.trim();
}
async function containers() {
  const ids = (await invoke('docker', ['ps', '-a', '--no-trunc', '--format', '{{.ID}}'])).split(/\r?\n/).filter(Boolean);
  if (!ids.length) return [];
  const rows = (await invoke('docker', ['container', 'inspect', '--format', format, ...ids])).split(/\r?\n/).filter(Boolean).map(JSON.parse);
  for (const row of rows) {
    row.mounts.sort((a, b) => a.Destination.localeCompare(b.Destination));
    row.networks = Object.keys(row.networks ?? {}).sort();
  }
  return rows.sort((a, b) => a.id.localeCompare(b.id));
}
function hashes() {
  return files.map((file) => ({ path: file, sha256: sha(fs.readFileSync(path.join(root, file))) }));
}
async function runProbe() {
  const bootstrap = 'import base64,sys;exec(compile(base64.b64decode(sys.stdin.buffer.readline()),"story_2_2_tick_trace","exec"))';
  const child = spawn('wsl.exe', ['-d', 'Ubuntu-24.04', '-u', 'root', '--', 'python3', '-u', '-c', bootstrap, group],
    { cwd: root, windowsHide: true, stdio: ['pipe', 'pipe', 'pipe'] });
  let start;
  let timer;
  let readyTimer;
  let stream = '';
  let bytes = 0;
  let result;
  let protocolError;
  const errors = [];
  child.stdin.on('error', (error) => { protocolError ??= error.message; });
  const stop = () => { if (!child.stdin.destroyed) child.stdin.end('{"command":"stop"}\n'); };
  process.once('SIGINT', stop);
  child.stderr.on('data', (chunk) => { if (errors.reduce((n,b)=>n+b.length,0) < 65536) errors.push(chunk); });
  const completion = new Promise((resolve, reject) => {
    child.on('error', reject);
    child.on('close', (code) => resolve(code));
  });
  child.stdout.on('data', (chunk) => {
    try {
      bytes += chunk.length;
      if (bytes > 2 * 1024 * 1024) throw new Error('跟踪协议输出超限');
      stream += chunk.toString('utf8');
      let newline;
      while ((newline = stream.indexOf('\n')) >= 0) {
        const line = stream.slice(0, newline).trim();
        stream = stream.slice(newline + 1);
        if (!line) continue;
        const message = JSON.parse(line);
        if (message.kind === 'ready') {
          if (start) throw new Error('重复 ready');
          clearTimeout(readyTimer);
          report.buffer_total_kib = message.buffer_total_kib;
          start = process.hrtime.bigint();
          timer = setTimeout(stop, 27000);
          child.stdin.write('{"command":"start"}\n');
          console.log('开始本次有界跟踪，最多 30 秒。');
        } else if (message.kind === 'control_verified') {
          console.log('只读对照已配对：trace PID ' + message.trace_pid + '，Ubuntu PID ' + message.local_pid + '。');
        } else if (message.kind === 'tick_write') {
          console.log('捕获 ADJ_TICK：PID ' + message.trace_pid + '，' + message.comm + '，tick=' + message.tick + '，返回=' + message.result + '。');
        } else if (message.kind === 'trace_stopped') {
          clearTimeout(timer);
          report.enabled_duration_host_upper_ms = Number(process.hrtime.bigint() - start) / 1e6;
          console.log('本次跟踪已停止，正在核对清理。');
        } else if (message.kind === 'result') {
          result = message.report;
        }
      }
    } catch (error) {
      protocolError ??= error.message;
      stop();
    }
  });
  readyTimer = setTimeout(stop, 10000);
  child.stdin.write(Buffer.from(pythonSource, 'utf8').toString('base64') + '\n');
  const code = await completion;
  clearTimeout(timer);
  clearTimeout(readyTimer);
  process.removeListener('SIGINT', stop);
  child.stdin.destroy();
  report.probe_exit_code = code;
  report.trace = result ?? { status: 'failed', error: '探针没有返回结果' };
  if (protocolError) report.protocol_error = protocolError;
  const stderr = Buffer.concat(errors);
  if (stderr.length) report.probe_stderr = stderr.includes(0) ? stderr.toString('utf16le') : stderr.toString('utf8');
  report.total_capture_host_upper_ms = (report.enabled_duration_host_upper_ms ?? 0) + report.previous_capture_host_upper_ms;
  if (code === 0 && !protocolError && report.total_capture_host_upper_ms <= 30000) report.status = 'completed';
}

let baselineContainers;
let baselineFiles;
try {
  if (fs.existsSync(evidencePath)) throw new Error('证据文件已存在');
  const head = await invoke('git', ['rev-parse', 'HEAD']);
  if (head !== report.baseline_commit) throw new Error('Git 基线变化');
  baselineContainers = await containers();
  baselineFiles = hashes();
  console.log('保留基线：' + baselineContainers.length + ' 个既有容器，' + baselineFiles.length + ' 个文件。');
  await runProbe();
} catch (error) {
  report.error = String(error.message ?? error);
} finally {
  try {
    if (baselineContainers && baselineFiles) {
      const afterContainers = await containers();
      const afterFiles = hashes();
      const comparedContainers = baselineContainers.map((before) => {
        const after = afterContainers.find((row) => row.id === before.id);
        const changed = Object.keys(before).filter((field) => JSON.stringify(before[field]) !== JSON.stringify(after?.[field]));
        return { id: before.id, name: before.name, unchanged: changed.length === 0, changed_fields: changed };
      });
      const comparedFiles = baselineFiles.map((before) => ({
        path: before.path, sha256_before: before.sha256,
        sha256_after: afterFiles.find((file) => file.path === before.path)?.sha256
      }));
      const added = afterContainers.filter((row) => !baselineContainers.some((before) => before.id === row.id)).map((row) => row.id);
      report.preservation = {
        containers: comparedContainers, files: comparedFiles, new_container_ids: added,
        normalization: '挂载按 Destination 排序，网络名排序；只读比较容器元数据与文件哈希',
        passed: !added.length && comparedContainers.every((row) => row.unchanged) &&
          comparedFiles.every((row) => row.sha256_before === row.sha256_after)
      };
      if (!report.preservation.passed) report.status = 'failed';
    }
  } catch (error) {
    report.preservation = { passed: false, error: String(error.message ?? error) };
    report.status = 'failed';
  }
  report.finished_at = new Date().toISOString();
  fs.writeFileSync(evidencePath, JSON.stringify(report, null, 2) + '\n', { encoding: 'utf8', flag: 'wx' });
  console.log(JSON.stringify({ status: report.status, trace_status: report.trace?.status,
    write_calls: report.trace?.writes?.length ?? 0, cleanup: report.trace?.cleanup,
    preserved: report.preservation?.passed, evidence: evidencePath,
    error: report.error ?? report.trace?.error ?? report.protocol_error ?? null }));
}
process.exitCode = report.status === 'completed' ? 0 : 1;

